import org.junit.Test;
import static org.junit.Assert.*;
import org.jsoup.nodes.TextNode;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.mockito.Mockito;

public class TextNodeTest {

    @Test
    public void createTextNodeEmptyStringTest() {
        String text = "";
        TextNode node = new TextNode(text);
        assertTrue(node.text().isEmpty());
    }

    @Test
    public void createTextNodeSingleCharacterTest() {
        String text = "a";
        TextNode node = new TextNode(text);
        assertEquals("a", node.text());
    }

    @Test
    public void createTextNodeMultipleCharactersTest() {
        String text = "ab c";
        TextNode node = new TextNode(text);
        assertEquals("ab c", node.text());
    }

    @Test
    public void nodeNameTest() {
        TextNode node = new TextNode("");
        assertEquals("#text", node.nodeName());
    }

    @Test
    public void textMethodReturnsNormalisedWhitespaceTest() {
        String text = "  ";
        TextNode node = new TextNode(text);
        assertEquals(StringUtil.normaliseWhitespace("  "), node.text());
    }

    @Test
    public void textSetTest() {
        String text = "ab c";
        TextNode node = new TextNode("");
        node.text(text);
        assertEquals(text, node.text());
    }

    @Test
    public void getWholeTextReturnsEncodedTextTest() {
        String encodedText = "&lt;";
        TextNode node = TextNode.createFromEncoded(encodedText);
        assertEquals(encodedText, node.getWholeText());
    }

    @Test
    public void isBlankTestFalseTest() {
        TextNode node = new TextNode("ab c");
        assertFalse(node.isBlank());
    }

    @Test
    public void isBlankTestTrueTest() {
        TextNode node = new TextNode("");
        assertTrue(node.isBlank());
    }

    @Test
    public void splitTextOffsetEqualsZeroTest() {
        String text = "ab c";
        TextNode node = new TextNode(text);
        TextNode result = node.splitText(0);
        assertEquals("ab", result.text());
        assertEquals("c", node.getWholeText().substring(node.splitText(0).splitText(1)));
    }

    @Test
    public void splitTextOffsetGreaterThanZeroTest() {
        String text = "ab c";
        TextNode node = new TextNode(text);
        TextNode result = node.splitText(2);
        assertEquals("c", result.text());
        assertEquals("ab ", node.getWholeText().substring(node.splitText(0).splitText(1)));
    }

    @Test
    public void splitTextOffsetEqualsLengthOfTextTest() {
        String text = "ab c";
        TextNode node = new TextNode(text);
        TextNode result = node.splitText(text.length());
        assertEquals("", result.text());
        assertEquals("ab", node.getWholeText().substring(0, node.splitText(0).splitText(1)));
    }

    @Test
    public void outerHtmlHeadTest() {
        StringBuilder builder = new StringBuilder();
        Document.OutputSettings out = new Document.OutputSettings(true);
        TextNode node = new TextNode("  ");
        node.outerHtmlHead(builder, 0, out);
        assertTrue(builder.toString().contains("<br>"));
    }

    @Test
    public void outerHtmlTailTest() {
        StringBuilder builder = new StringBuilder();
        Document.OutputSettings out = new Document.OutputSettings(false);
        TextNode node = new TextNode("ab c");
        node.outerHtmlTail(builder, 0, out);
    }

    @Test
    public void toStringTest() {
        String text = "ab c";
        TextNode node = new TextNode(text);
        assertEquals("<p>ab c</p>", node.toString());
    }

    @Test
    public void cloneTest() {
        TextNode node = new TextNode("ab c");
        TextNode cloned = node.clone();
        assertEquals(node.text(), cloned.text());
    }
}
